    CHECK(xuiDocumentRedo(target, NULL) == XUI_OK);
    CHECK(xuiDocumentAcquireSnapshot(target, &after) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetNode(after, first, &info) == XUI_OK);
    xuiDocumentSnapshotRelease(after); xuiDocumentRelease(target);

