    CHECK(xuiDocumentBeginTransaction(origin, NULL, &t) == XUI_OK);
    CHECK(xuiDocumentTxnInsertTable(t, 1, 0, 1, 2, 0, &table) == XUI_OK);
    CHECK(xuiDocumentTxnPasteTableMatrix(t, table, 0, 0, "ab\tcd", 5, &a) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentAcquireSnapshot(origin, &source) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(source, table, 0, &row) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(source, row, 0, &cell) == XUI_OK);
    a = find_kind(source, cell, XUI_DOC_TEXT);
    CHECK(xuiDocumentSnapshotGetChild(source, row, 1, &cell) == XUI_OK);
    b = find_kind(source, cell, XUI_DOC_TEXT);
    CHECK(a && b);
    range.tAnchor = copy_range_position(origin, a, XUI_DOC_POSITION_TEXT, 1);
    range.tCaret = copy_range_position(origin, b, XUI_DOC_POSITION_TEXT, 1);
    CHECK(xuiDocumentCreate(NULL, &target) == XUI_OK);
    revision = xuiDocumentGetRevision(target);
    CHECK(xuiDocumentBeginTransaction(target, NULL, &t) == XUI_OK);
    CHECK(xuiDocumentTxnCopyRange(t, source, &range, 1, 0,
        &first, &count) == XUI_ERROR_UNSUPPORTED && !first && !count);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_ERROR_UNSUPPORTED);
    xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentGetRevision(target) == revision);
    CHECK(xuiDocumentAcquireSnapshot(target, &after) == XUI_OK);
    info.iSize = sizeof(info);
    CHECK(xuiDocumentSnapshotGetNode(after, 1, &info) == XUI_OK && !info.iChildCount);
    xuiDocumentSnapshotRelease(after); xuiDocumentRelease(target);
    xuiDocumentSnapshotRelease(source); xuiDocumentRelease(origin);
    puts("Document range copy: partial table selection rejects atomically");
