    xui_doc_node_desc_t desc = {0}; xui_doc_node_info_t info = {0};
    xui_doc_desc_t md = {0}; xui_doc_range_t range;
    uint64_t p1, p2, a, b, c, d, first, count, node, child, bytes;
    char *wire = NULL, *source_text = NULL, *html = NULL;
    uint64_t html_bytes = 0;
    CHECK(xuiDocumentCreate(NULL, &source_doc) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(source_doc, NULL, &t) == XUI_OK);
    p1 = insert(t, 1, XUI_DOC_PARAGRAPH, NULL);
    desc.iSize = sizeof(desc); desc.iKind = XUI_DOC_TEXT;
    desc.sText = "aβ"; desc.iTextBytes = strlen(desc.sText);
    desc.tAttributes.iMarks = XUI_DOC_BOLD;
