    desc.sText = "ef"; desc.iTextBytes = 2;
    desc.tAttributes.iMarks = XUI_DOC_LINK;
    desc.sResource = "https://example.test/fragment";
    CHECK(xuiDocumentTxnInsertNode(t, p1, UINT64_MAX, &desc, &c) == XUI_OK);
    p2 = insert(t, 1, XUI_DOC_PARAGRAPH, NULL);
    d = insert(t, p2, XUI_DOC_TEXT, "world");
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentAcquireSnapshot(source_doc, &source) == XUI_OK);

    range.tAnchor = copy_range_position(source_doc, a, XUI_DOC_POSITION_TEXT, 1);
    range.tCaret = copy_range_position(source_doc, d, XUI_DOC_POSITION_TEXT, 3);
