    CHECK(xuiDocumentBeginTransaction(target, NULL, &t) == XUI_OK);
    CHECK(xuiDocumentTxnInsertFragment(t, restored, 1, 0,
        &first, &count) == XUI_OK && count == 2);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentAcquireSnapshot(target, &after) == XUI_OK);
    info.iSize = sizeof(info);
    CHECK(xuiDocumentSnapshotGetNode(after, first, &info) == XUI_OK &&
        info.iKind == XUI_DOC_PARAGRAPH && info.iChildCount == 3);
    CHECK(xuiDocumentSnapshotGetChild(after, first, 0, &child) == XUI_OK);
    expect_text(after, child, "β");
    CHECK(xuiDocumentSnapshotGetNode(after, child, &info) == XUI_OK &&
        info.tAttributes.iMarks == XUI_DOC_BOLD);
    CHECK(xuiDocumentSnapshotGetChild(after, first, 2, &child) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetNode(after, child, &info) == XUI_OK &&
        info.tAttributes.iMarks == XUI_DOC_LINK &&
        !strcmp(info.sResource, "https://example.test/fragment"));
    CHECK(xuiDocumentSnapshotGetChild(after, 1, 1, &node) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(after, node, 0, &child) == XUI_OK);
    expect_text(after, child, "wor");
    xuiDocumentSnapshotRelease(after);
    CHECK(xuiDocumentUndo(target, NULL) == XUI_OK);
    CHECK(xuiDocumentRedo(target, NULL) == XUI_OK);
    xuiDocumentRelease(target);

    CHECK(xuiDocumentCreate(NULL, &target) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(target, NULL, &t) == XUI_OK);
    p1 = insert(t, 1, XUI_DOC_PARAGRAPH, NULL);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentBeginTransaction(target, NULL, &t) == XUI_OK);
    CHECK(xuiDocumentTxnInsertFragment(t, inline_fragment, p1, 0,
        &first, &count) == XUI_OK && count == 2);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentAcquireSnapshot(target, &after) == XUI_OK);
    expect_text(after, first, "β");
    CHECK(xuiDocumentSnapshotGetChild(after, p1, 1, &child) == XUI_OK);
    expect_text(after, child, "C");
    CHECK(xuiDocumentSnapshotGetNode(after, child, &info) == XUI_OK &&
        info.tAttributes.iMarks == XUI_DOC_ITALIC);
    xuiDocumentSnapshotRelease(after); xuiDocumentRelease(target);

    md.iSize = sizeof(md); md.iProfile = XUI_DOCUMENT_MARKDOWN;
    md.iMarkdownDialect = XUI_MD_GFM;
    CHECK(xuiDocumentCreate(&md, &target) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(target, NULL, &t) == XUI_OK);
    CHECK(xuiDocumentTxnInsertFragment(t, restored, 1, 0,
        &first, &count) == XUI_OK && count == 2);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentAcquireSnapshot(target, &after) == XUI_OK);
    CHECK(xuiDocumentSnapshotCopySource(after, NULL, 0, &bytes) == XUI_OK);
    source_text = malloc((size_t)bytes + 1); CHECK(source_text);
    CHECK(xuiDocumentSnapshotCopySource(after, source_text, bytes + 1, &bytes) == XUI_OK &&
        strstr(source_text, "wor") && strstr(source_text, "example"));
    free(source_text); xuiDocumentSnapshotRelease(after);
    CHECK(xuiDocumentUndo(target, NULL) == XUI_OK);
    xuiDocumentRelease(target);
    xuiDocumentFragmentRelease(restored);
    xuiDocumentFragmentRelease(inline_fragment);
    puts("Native fragment: independent snapshot, inline/block roots, serialization, Rich/Markdown insertion and Undo passed");
