    CHECK(xuiDocumentCreate(NULL, &target) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(target, NULL, &transaction) == XUI_OK);
    paragraph = insert(transaction, 1, XUI_DOC_PARAGRAPH, NULL);
