static void html_container_style_roundtrip(void)
{
    static const char input[] =
        "<body style=\"color:#112233;font-size:18px;font-family:Demo\">"
        "<div style=\"font-weight:700;text-align:right\">"
        "<p>outer</p>"
        "<div style=\"font-weight:normal;color:#445566\">loose<p>inner</p>"
        "<ul><li><p>item</p></li></ul></div>"
        "<p>again</p></div>"
        "<table style=\"color:#667788;font-weight:700;text-align:center\">"
        "<tr style=\"font-size:22px\"><td style=\"font-weight:normal\">"
        "<p>cell</p></td></tr></table></body>";
    const char* texts[6] = {"outer", "loose", "inner", "item", "again", "cell"};
    const uint32_t colors[6] = {0x112233ffu, 0x445566ffu,
        0x445566ffu, 0x445566ffu, 0x112233ffu, 0x667788ffu};
    const uint32_t marks[6] = {XUI_DOC_BOLD, 0, 0, 0, XUI_DOC_BOLD, 0};
    xui_document_fragment fragment = NULL, roundtrip = NULL;
    xui_document document = NULL, restored = NULL;
    xui_document_transaction transaction = NULL;
    xui_document_snapshot snapshot = NULL;
    char* html = NULL;
    uint64_t bytes = 0, first = 0, count = 0, root_child, paragraph, text_node;
    unsigned pass, i;
    CHECK(xuiDocumentFragmentImportHtml(input, sizeof(input) - 1, &fragment) == XUI_OK);
    for (pass = 0; pass < 2; pass++) {
        xui_document current = NULL;
        xui_document_fragment current_fragment = pass ? roundtrip : fragment;
        CHECK(xuiDocumentCreate(NULL, pass ? &restored : &document) == XUI_OK);
        current = pass ? restored : document;
        CHECK(xuiDocumentBeginTransaction(current, NULL, &transaction) == XUI_OK);
        CHECK(xuiDocumentTxnInsertFragment(transaction, current_fragment, 1, 0,
            &first, &count) == XUI_OK && count == 6);
        CHECK(xuiDocumentTxnCommit(transaction, NULL) == XUI_OK);
        xuiDocumentTxnRelease(transaction); transaction = NULL;
        CHECK(xuiDocumentAcquireSnapshot(current, &snapshot) == XUI_OK);
        for (i = 0; i < 6; i++) {
            xui_doc_node_info_t block = {0}, leaf = {0};
            CHECK(xuiDocumentSnapshotGetChild(snapshot, 1, i, &root_child) == XUI_OK);
            if (i == 3) {
                uint64_t item;
                CHECK(xuiDocumentSnapshotGetChild(snapshot, root_child, 0, &item) == XUI_OK);
                CHECK(xuiDocumentSnapshotGetChild(snapshot, item, 0, &paragraph) == XUI_OK);
            } else if (i == 5) {
                uint64_t row, cell;
                CHECK(xuiDocumentSnapshotGetChild(snapshot, root_child, 0, &row) == XUI_OK);
                CHECK(xuiDocumentSnapshotGetChild(snapshot, row, 0, &cell) == XUI_OK);
                CHECK(xuiDocumentSnapshotGetChild(snapshot, cell, 0, &paragraph) == XUI_OK);
            } else paragraph = root_child;
            block.iSize = leaf.iSize = sizeof(block);
            CHECK(xuiDocumentSnapshotGetNode(snapshot, paragraph, &block) == XUI_OK &&
                block.iKind == XUI_DOC_PARAGRAPH &&
                block.tAttributes.iTextColor == colors[i] &&
                block.tAttributes.fFontSize == (i == 5 ? 22 : 18) &&
                block.tAttributes.iAlignment == (i == 5 ? 1 : 2) &&
                !strcmp(block.tAttributes.sFontFamily, "Demo"));
            CHECK(xuiDocumentSnapshotGetChild(snapshot, paragraph, 0, &text_node) == XUI_OK);
            CHECK(xuiDocumentSnapshotGetNode(snapshot, text_node, &leaf) == XUI_OK &&
                leaf.iKind == XUI_DOC_TEXT && leaf.tAttributes.iMarks == marks[i]);
            expect_text(snapshot, text_node, texts[i]);
        }
        if (!pass) {
            CHECK(xuiDocumentExportHtml(snapshot, &html, &bytes) == XUI_OK);
            CHECK(xuiDocumentFragmentImportHtml(html, bytes, &roundtrip) == XUI_OK);
            xuiDocumentFreeBuffer(html); html = NULL;
        }
        xuiDocumentSnapshotRelease(snapshot); snapshot = NULL;
    }
    xuiDocumentFragmentRelease(roundtrip); xuiDocumentFragmentRelease(fragment);
    xuiDocumentRelease(restored); xuiDocumentRelease(document);
    puts("HTML container style inheritance: nested blocks, implicit paragraph, list/table cells and roundtrip passed");
}
