    CHECK(xuiDocumentAcquireSnapshot(d, &after) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetTableColumnWidth(after, table, 0, &width) == XUI_OK && width == 0);
    xuiDocumentSnapshotRelease(after);
    CHECK(xuiDocumentRedo(d, NULL) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
    CHECK(xuiDocumentTxnInsertTableColumn(t, table, 1) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentAcquireSnapshot(d, &after) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetTableColumnWidth(after, table, 0, &width) == XUI_OK && width == 35);
    CHECK(xuiDocumentSnapshotGetTableColumnWidth(after, table, 1, &width) == XUI_OK && width == 0);
    CHECK(xuiDocumentSnapshotGetTableColumnWidth(after, table, 2, &width) == XUI_OK && width == 0);
    CHECK(xuiDocumentSnapshotGetTableColumnWidth(after, table, 3, &width) == XUI_OK && width == 20);
    xuiDocumentSnapshotRelease(after);
