    CHECK(xuiDocumentTxnDeleteTableRow(t, table, 0) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentAcquireSnapshot(d, &after) == XUI_OK);
