    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_DOC_ERROR_UNREPRESENTABLE); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentGetRevision(markdown) == revision); xuiDocumentRelease(markdown);
