            range.tAnchor.iKind = mode ? XUI_DOC_POSITION_TEXT : XUI_DOC_POSITION_GAP; range.tAnchor.iNodeId = id; range.tAnchor.iOffset = mode ? 2 : 0; range.tCaret = range.tAnchor;
