        xui_document d = test_markdown_open(ordered); xui_document_transaction t;
        xui_document_snapshot s; xui_doc_range_t range, after, b_range = test_find(d, "B"), c_range = test_find(d, "C");
        xui_doc_node_info_t info = {0}; uint64_t tail;
        range.tAnchor = b_range.tAnchor; range.tCaret = c_range.tCaret;
        CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
        CHECK(xuiDocumentTxnOutdentListRange(t, &range, &after) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
