static void markdown_table_editing(void)
{
    const char* original = "before\r\n\r\n| H | B |\r\n| :---: | ---: |\r\n| alpha | beta |\r\n\r\nafter  \r\n";
    xui_document d = test_markdown_open(original); xui_document_snapshot s; xui_document_transaction t;
    xui_doc_node_info_t info = {0}; uint64_t table, row, cell, i;
    info.iSize = sizeof(info); CHECK(xuiDocumentAcquireSnapshot(d, &s) == XUI_OK); table = find_kind(s, 1, XUI_DOC_TABLE); xuiDocumentSnapshotRelease(s);
    CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
    CHECK(xuiDocumentTxnInsertTableRow(t, table, 0) == XUI_OK);
    CHECK(xuiDocumentTxnInsertTableColumn(t, table, 1) == XUI_OK);
    CHECK(xuiDocumentTxnDeleteTableRow(t, table, 1) == XUI_OK);
    CHECK(xuiDocumentTxnDeleteTableColumn(t, table, 1) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    test_source(d, "before\r\n\r\n", 0); test_source(d, "after  \r\n", 0);
    CHECK(xuiDocumentAcquireSnapshot(d, &s) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetNode(s, table, &info) == XUI_OK && info.iChildCount == 2);
    for (i = 0; i < 2; i++) {
        CHECK(xuiDocumentSnapshotGetChild(s, table, i, &row) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetChild(s, row, 0, &cell) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetNode(s, cell, &info) == XUI_OK && info.tAttributes.iAlignment == 1);
        CHECK(!!(info.tAttributes.iFlags & XUI_DOC_HEADER) == !i);
    }
    xuiDocumentSnapshotRelease(s); CHECK(xuiDocumentUndo(d, NULL) == XUI_OK); test_source(d, original, 1); xuiDocumentRelease(d);
    d = test_markdown_open(""); CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
    CHECK(xuiDocumentTxnInsertTable(t, 1, 0, 2, 2, 1, &table) == XUI_OK);
    CHECK(xuiDocumentTxnInsertTableRow(t, table, 2) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    CHECK(xuiDocumentAcquireSnapshot(d, &s) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetNode(s, table, &info) == XUI_OK && info.iChildCount == 3);
    xuiDocumentSnapshotRelease(s); xuiDocumentRelease(d);
}
