static void markdown_table_row_source_failures(void)
{
    const char* original =
        "lead &amp;\r\n\r\n| A | B |\r\n| :--: | ---: |\r\n"
        "| x | y |\r\n| z | w |\r\n\r\nend &amp;\r\n";
    const char* updated[] = {
        "lead &amp;\r\n\r\n| A | B |\r\n| :--: | ---: |\r\n"
        "| x | y |\r\n|  |  |\r\n| z | w |\r\n\r\nend &amp;\r\n",
        "lead &amp;\r\n\r\n| A | B |\r\n| :--: | ---: |\r\n"
        "| z | w |\r\n\r\nend &amp;\r\n"
    };
    unsigned mode;
    for (mode = 0; mode < 2; mode++) {
        long point;
        int succeeded = 0;
        for (point = 0; point < 1024 && !succeeded; point++) {
            fail_allocator allocator = {-1, 0};
            xui_doc_desc_t desc = {0};
            xui_document document = NULL;
            xui_document_snapshot before = NULL, after = NULL;
            xui_document_transaction transaction = NULL;
            uint64_t table, revision;
            int result, can_undo;
            desc.iSize = sizeof(desc); desc.iProfile = XUI_DOCUMENT_MARKDOWN;
            desc.iMarkdownDialect = XUI_MD_GFM;
            desc.onAlloc = failing_alloc; desc.onFree = failing_free;
            desc.pAllocatorUser = &allocator;
            CHECK(xuiDocumentCreate(&desc, &document) == XUI_OK);
            CHECK(xuiDocumentLoadMarkdown(document, original, strlen(original)) == XUI_OK);
            CHECK(xuiDocumentAcquireSnapshot(document, &before) == XUI_OK);
            table = find_kind(before, XUI_DOCUMENT_ROOT, XUI_DOC_TABLE);
            CHECK(table != 0);
            revision = xuiDocumentGetRevision(document);
            can_undo = xuiDocumentCanUndo(document);
            allocator.remaining = point;
            result = xuiDocumentBeginTransaction(document, NULL, &transaction);
            if (result == XUI_OK) result = mode ?
                xuiDocumentTxnDeleteTableRow(transaction, table, 1) :
                xuiDocumentTxnInsertTableRow(transaction, table, 2);
            if (result == XUI_OK) result = xuiDocumentTxnCommit(transaction, NULL);
            if (transaction) xuiDocumentTxnRelease(transaction);
            allocator.remaining = -1;
            if (result == XUI_OK) {
                succeeded = 1;
                test_source(document, updated[mode], 1);
                CHECK(xuiDocumentUndo(document, NULL) == XUI_OK);
                test_source(document, original, 1);
            } else {
                CHECK(result == XUI_ERROR_OUT_OF_MEMORY &&
                    xuiDocumentGetRevision(document) == revision &&
                    xuiDocumentCanUndo(document) == can_undo);
                test_source(document, original, 1);
                CHECK(xuiDocumentAcquireSnapshot(document, &after) == XUI_OK);
                expect_identity_tree(before, after, XUI_DOCUMENT_ROOT);
                expect_same_syntax(before, after);
                xuiDocumentSnapshotRelease(after);
            }
            xuiDocumentSnapshotRelease(before);
            xuiDocumentRelease(document);
            CHECK(allocator.live == 0);
        }
        CHECK(succeeded);
        printf("Markdown table data-row %s allocation-failure sweep: %ld points; atomic source/tree/history and no leaks passed\n",
            mode ? "delete" : "insert", point);
    }
}
