        size_t at = 0;
        char* long_source = malloc(12 + lines * 4 + 1);
        xui_doc_block_syntax_t syntax = {0};
        uint64_t last_start = 0, last_end = 0;
        CHECK(long_source != NULL);
        memcpy(long_source + at, "- ~~~\n", 6); at += 6;
        for (i = 0; i < lines; i++) { memcpy(long_source + at, "  x\n", 4); at += 4; }
