        CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
        CHECK(xuiDocumentTxnReplaceRange(t, &range, "\n", 1, &caret) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
        CHECK(xuiDocumentAcquireSnapshot(d, &s) == XUI_OK);
        CHECK(xuiDocumentSnapshotCopySource(s, source, sizeof(source), &bytes) == XUI_OK);
        if (cases[i].expected) CHECK(!strcmp(source, cases[i].expected));
