    caret.iRevision = xuiDocumentGetRevision(d); range.tAnchor = range.tCaret = caret;
    CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
    CHECK(xuiDocumentTxnReplaceRange(t, &range, "X", 1, &caret) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
    range = test_find(d, "omegaX"); CHECK(range.tAnchor.iNodeId); test_source(d, "TAIL\n", 0);
    CHECK(xuiDocumentUndo(d, NULL) == XUI_OK); CHECK(xuiDocumentUndo(d, NULL) == XUI_OK); test_source(d, input, 1); xuiDocumentRelease(d);
