        xui_doc_position_t before = test_find(d, "abc").tAnchor, after, mapped; xui_document_snapshot s; int mapping;
        before.iOffset = 1; before.iAffinity = XUI_DOC_BEFORE; after = before; after.iAffinity = XUI_DOC_AFTER;
