        CHECK(xuiDocumentTxnCommit(t, &change) == XUI_OK); xuiDocumentTxnRelease(t);
        expect_map(d, change, before, before.iNodeId, XUI_DOC_POSITION_TEXT, 1, XUI_DOC_MAP_EXACT);
