    unsigned i;
    for (i = 0; i < sizeof(cases) / sizeof(*cases); i++) {
        xui_document d = test_markdown_open(cases[i].input), parsed;
        xui_document_transaction t; xui_document_snapshot current, reloaded;
        xui_doc_range_t range, first = test_find(d, "keep"), last = test_find(d, "right");
        xui_doc_position_t caret; int order, replace_result;
        range.tAnchor = first.tAnchor; range.tCaret = last.tCaret;
        if (cases[i].reverse) {
            xui_doc_position_t swap = range.tAnchor;
            range.tAnchor = range.tCaret; range.tCaret = swap;
        }
        CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
        replace_result = xuiDocumentTxnReplaceRange(t, &range, "JOIN", 4, &caret);
        if (replace_result != XUI_OK)
            fprintf(stderr, "cross-parent case %u replace result %d\n", i, replace_result);
        CHECK(replace_result == XUI_OK);
        CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
        test_source(d, cases[i].expected, 1);
        CHECK(xuiDocumentAcquireSnapshot(d, &current) == XUI_OK);
        if (strstr(cases[i].input, "   - [one]: /raw-1")) {
            xui_doc_source_info_t source_info = {0};
            source_info.iSize = sizeof(source_info);
            CHECK(xuiDocumentSnapshotGetSourceInfo(current, &source_info) == XUI_OK &&
                source_info.iReferenceDefinitionCount == 2);
        }
        if (strstr(cases[i].input, "body &amp; gone\n    [unused]: /raw \"T\"")) {
            xui_doc_source_info_t source_info = {0};
            source_info.iSize = sizeof(source_info);
            CHECK(xuiDocumentSnapshotGetSourceInfo(current, &source_info) == XUI_OK &&
                source_info.iReferenceDefinitionCount == 0);
        } else if (strstr(cases[i].input, "    [unused]: /raw \"T\"") ||
            strstr(cases[i].input, "    [r]: /raw \"T\"")) {
            xui_doc_source_info_t source_info = {0};
            source_info.iSize = sizeof(source_info);
            CHECK(xuiDocumentSnapshotGetSourceInfo(current, &source_info) == XUI_OK &&
                source_info.iReferenceDefinitionCount == 1);
        }
        if (strstr(cases[i].input, "  - [unused]: /raw \"T\"\n  - >") ||
            i + 6 == sizeof(cases) / sizeof(*cases) ||
            (i + 4 >= sizeof(cases) / sizeof(*cases) &&
                i + 1 != sizeof(cases) / sizeof(*cases))) {
            xui_doc_source_info_t source_info = {0};
            source_info.iSize = sizeof(source_info);
            CHECK(xuiDocumentSnapshotGetSourceInfo(current, &source_info) == XUI_OK &&
                source_info.iReferenceDefinitionCount == 1);
        }
        caret.iRevision = xuiDocumentGetRevision(d);
        CHECK(xuiDocumentSnapshotComparePositions(current, &caret, &caret, &order) == XUI_OK);
        parsed = test_markdown_open(cases[i].expected);
        CHECK(xuiDocumentAcquireSnapshot(parsed, &reloaded) == XUI_OK);
        expect_same_syntax(current, reloaded);
        xuiDocumentSnapshotRelease(reloaded); xuiDocumentSnapshotRelease(current);
        xuiDocumentRelease(parsed);
        CHECK(xuiDocumentUndo(d, NULL) == XUI_OK); test_source(d, cases[i].input, 1);
        CHECK(xuiDocumentRedo(d, NULL) == XUI_OK); test_source(d, cases[i].expected, 1);
        xuiDocumentRelease(d);
    }
