        expect_same_syntax(snapshot, parsed);
        xuiDocumentSnapshotRelease(parsed);
        xuiDocumentSnapshotRelease(snapshot);
        xuiDocumentRelease(reloaded);
        CHECK(xuiDocumentUndo(d, NULL) == XUI_OK);
        test_source(d, input, 1);
        CHECK(xuiDocumentRedo(d, NULL) == XUI_OK);
        test_source(d, expected, 1);
        xuiDocumentRelease(d);
