    expect_inline_syntax(s, 1, XUI_DOC_SYNTAX_STRONG, 0, 1, 3, close, close + 2, UINT64_MAX);
    expect_inline_syntax(s, 2, XUI_DOC_SYNTAX_LINK, 1, link, link + 1, link + 2, link + 8, 0);
