static void extended_markdown_mark_failures(void)
{
    const char* inputs[] = {"PRE\n\nplain\n\nTAIL\n", "==plain==\n"};
    unsigned mode;
    for (mode = 0; mode < 2; mode++) {
        long point; int success = 0;
        for (point = 0; point < 1000 && !success; point++) {
            fail_allocator a = {-1, 0}; xui_doc_desc_t desc = {0}; xui_document d;
            xui_document_transaction t = NULL; xui_document_snapshot before, after;
            xui_doc_range_t range; uint64_t revision; int result, can_undo;
            desc.iSize = sizeof(desc); desc.iProfile = XUI_DOCUMENT_MARKDOWN; desc.iMarkdownDialect = XUI_MD_EXTENDED;
            desc.onAlloc = failing_alloc; desc.onFree = failing_free; desc.pAllocatorUser = &a;
            CHECK(xuiDocumentCreate(&desc, &d) == XUI_OK && xuiDocumentLoadMarkdown(d, inputs[mode], strlen(inputs[mode])) == XUI_OK);
            CHECK(xuiDocumentAcquireSnapshot(d, &before) == XUI_OK);
            range = test_find(d, "plain"); revision = xuiDocumentGetRevision(d); can_undo = xuiDocumentCanUndo(d);
            a.remaining = point;
            result = xuiDocumentBeginTransaction(d, NULL, &t);
            if (result == XUI_OK) result = xuiDocumentTxnSetMarks(t, &range,
                mode ? 0 : XUI_DOC_HIGHLIGHT, mode ? XUI_DOC_HIGHLIGHT : 0);
            if (result == XUI_OK) result = xuiDocumentTxnCommit(t, NULL);
            xuiDocumentTxnRelease(t); a.remaining = -1;
            if (result == XUI_OK) success = 1;
            else {
                CHECK(result == XUI_ERROR_OUT_OF_MEMORY && xuiDocumentGetRevision(d) == revision &&
                    xuiDocumentCanUndo(d) == can_undo);
                CHECK(xuiDocumentAcquireSnapshot(d, &after) == XUI_OK);
                expect_identity_tree(before, after, 1); expect_same_syntax(before, after);
                xuiDocumentSnapshotRelease(after); test_source(d, inputs[mode], 1);
            }
            xuiDocumentSnapshotRelease(before); xuiDocumentRelease(d); CHECK(!a.live);
        }
        CHECK(success);
        printf("Extended Markdown %s allocation-failure sweep: %ld points; source/tree/history and no leaks passed\n",
            mode ? "clear" : "insert", point);
    }
}
static void link_range_failures(void)
{
    const char* sources[] = {NULL, "PRE\n\nplain\n\nTAIL\n", "[plain][ref]\n\n[ref]: /target\n",
        "one **two** three\n", "[plain](/target)\n"};
    const char* labels[] = {"rich", "Markdown insert", "Markdown clear", "Markdown styled insert", "Markdown partial clear"};
    unsigned mode;
    for (mode = 0; mode < 5; mode++) {
        long point; int success = 0;
        for (point = 0; point < 1000 && !success; point++) {
            fail_allocator a = {-1, 0}; xui_doc_desc_t desc = {0}; xui_document d;
            xui_document_transaction t = NULL; xui_document_snapshot before, after;
            xui_doc_range_t range; uint64_t revision; int result, can_undo;
            desc.iSize = sizeof(desc); desc.iProfile = mode ? XUI_DOCUMENT_MARKDOWN : XUI_DOCUMENT_RICH;
            desc.onAlloc = failing_alloc; desc.onFree = failing_free; desc.pAllocatorUser = &a;
            CHECK(xuiDocumentCreate(&desc, &d) == XUI_OK);
            if (mode) CHECK(xuiDocumentLoadMarkdown(d, sources[mode], strlen(sources[mode])) == XUI_OK);
            else {
                uint64_t p; CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
                p = insert(t, 1, XUI_DOC_PARAGRAPH, NULL); insert(t, p, XUI_DOC_TEXT, "plain");
                CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t); t = NULL;
            }
            CHECK(xuiDocumentAcquireSnapshot(d, &before) == XUI_OK);
            range = test_find(d, mode == 3 ? "one two three" : mode == 4 ? "lai" : "plain");
            revision = xuiDocumentGetRevision(d); can_undo = xuiDocumentCanUndo(d);
            a.remaining = point;
            result = xuiDocumentBeginTransaction(d, NULL, &t);
            if (result == XUI_OK) result = xuiDocumentTxnSetLink(t, &range,
                mode == 2 || mode == 4 ? NULL : "/new", mode == 2 || mode == 4 ? NULL : "new");
            if (result == XUI_OK) result = xuiDocumentTxnCommit(t, NULL);
            xuiDocumentTxnRelease(t); a.remaining = -1;
            if (result == XUI_OK) success = 1;
            else {
                CHECK(result == XUI_ERROR_OUT_OF_MEMORY && xuiDocumentGetRevision(d) == revision &&
                    xuiDocumentCanUndo(d) == can_undo);
                CHECK(xuiDocumentAcquireSnapshot(d, &after) == XUI_OK);
                expect_identity_tree(before, after, 1); expect_same_syntax(before, after);
                xuiDocumentSnapshotRelease(after);
                if (mode) test_source(d, sources[mode], 1);
            }
            xuiDocumentSnapshotRelease(before); xuiDocumentRelease(d); CHECK(!a.live);
        }
        CHECK(success);
        printf("Link range %s allocation-failure sweep: %ld points; atomic source/tree/history and no leaks passed\n",
            labels[mode], point);
    }
}
