    CHECK(value <= 999); snprintf(text, sizeof(text), "%03u", value);
    td.iSize = sizeof(td); td.iDomain = XUI_DOC_SEMANTIC; td.iGroup = group; td.iOrigin = 17;
    CHECK(xuiDocumentBeginTransaction(d, &td, &t) == XUI_OK);
    CHECK(xuiDocumentTxnReplaceText(t, id, 0, 3, text, 3) == XUI_OK);
