    test_source(markdown, "[outer]: /target \"Link\"\r\n", 0);
    CHECK(xuiDocumentUndo(markdown, NULL) == XUI_OK); test_source(markdown, source, 1);
    CHECK(xuiDocumentRedo(markdown, NULL) == XUI_OK);
    image.sLinkTarget = "/other"; image.sLinkTitle = "Other";
    CHECK(xuiDocumentBeginTransaction(markdown, NULL, &txn) == XUI_OK);
    CHECK(xuiDocumentTxnUpdateImage(txn, image_id, &image) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK);
