        CHECK(xuiDocumentTxnUpdateImage(t, id, &image) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
        test_source(d, expected, 1);
