static void markdown_empty_cell_source_mapping(void)
{
    const char* text = "| A | B |\n| - | - |\n| x | y |\n|   |   |\n";
    xui_doc_desc_t desc = {0}; xui_document document; xui_document_snapshot snapshot;
    xui_doc_range_t match; xui_doc_position_t position, reverse;
    xui_doc_node_id table, row, cell; uint64_t found, offset, column;
    int mapping; unsigned affinity;
    desc.iSize = sizeof(desc); desc.iProfile = XUI_DOCUMENT_MARKDOWN;
    desc.iMarkdownDialect = XUI_MD_GFM;
    CHECK(xuiDocumentCreate(&desc, &document) == XUI_OK);
    CHECK(xuiDocumentLoadMarkdown(document, text, strlen(text)) == XUI_OK);
    CHECK(xuiDocumentAcquireSnapshot(document, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotFind(snapshot, XUI_DOC_SEMANTIC, "x", 1,
        NULL, &match, 1, &found) == XUI_OK && found == 1);
    CHECK(xuiDocumentPositionToSource(snapshot, &match.tAnchor, &offset, &mapping) == XUI_OK &&
        mapping == XUI_DOC_MAP_EXACT);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, 1, 0, &table) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, table, 2, &row) == XUI_OK);
    for (column = 0; column < 2; column++) {
        xui_doc_node_info_t info = {0}; info.iSize = sizeof(info);
        CHECK(xuiDocumentSnapshotGetChild(snapshot, row, column, &cell) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetNode(snapshot, cell, &info) == XUI_OK);
        CHECK(info.iSyntaxStart != UINT64_MAX && info.iSyntaxStart == info.iSyntaxEnd);
        for (affinity = XUI_DOC_BEFORE; affinity <= XUI_DOC_AFTER; affinity++) {
            position = match.tCaret;
            position.iKind = XUI_DOC_POSITION_GAP; position.iNodeId = cell;
            position.iOffset = 0; position.iAffinity = affinity;
            CHECK(xuiDocumentPositionToSource(snapshot, &position, &offset, &mapping) == XUI_OK &&
                mapping == XUI_DOC_MAP_SYNTAX && offset == info.iSyntaxStart);
            CHECK(xuiDocumentSourceToPositionEx(snapshot, offset, affinity, &reverse, &mapping) == XUI_OK &&
                mapping == XUI_DOC_MAP_SYNTAX && reverse.iNodeId == cell &&
                reverse.iKind == XUI_DOC_POSITION_GAP && reverse.iOffset == 0);
        }
    }
    CHECK(xuiDocumentSnapshotGetChild(snapshot, row, 0, &cell) == XUI_OK);
    xuiDocumentSnapshotRelease(snapshot);
    {
        xui_document_transaction txn;
        xui_doc_position_t caret = {0};
        match.tAnchor = match.tCaret = test_position(document, cell,
            XUI_DOC_POSITION_GAP, 0, XUI_DOC_AFTER);
        CHECK(xuiDocumentBeginTransaction(document, NULL, &txn) == XUI_OK);
        CHECK(xuiDocumentTxnReplaceRange(txn, &match, "new|cell", 8, &caret) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
        test_source(document, "| A | B |\n| - | - |\n| x | y |\n|   new\\|cell|   |\n", 1);
        CHECK(xuiDocumentAcquireSnapshot(document, &snapshot) == XUI_OK);
        CHECK(xuiDocumentSnapshotFind(snapshot, XUI_DOC_SEMANTIC, "new|cell", 8,
            NULL, NULL, 0, &found) == XUI_OK && found == 1);
        xuiDocumentSnapshotRelease(snapshot);
        CHECK(xuiDocumentUndo(document, NULL) == XUI_OK);
        test_source(document, text, 1);
        CHECK(xuiDocumentRedo(document, NULL) == XUI_OK);
        test_source(document, "| A | B |\n| - | - |\n| x | y |\n|   new\\|cell|   |\n", 1);
    }
    xuiDocumentRelease(document);
    text = "| A | B |\r\n| - | - |\r\n|||\r\n";
    CHECK(xuiDocumentCreate(&desc, &document) == XUI_OK);
    CHECK(xuiDocumentLoadMarkdown(document, text, strlen(text)) == XUI_OK);
    CHECK(xuiDocumentAcquireSnapshot(document, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotFind(snapshot, XUI_DOC_SEMANTIC, "A", 1,
        NULL, &match, 1, &found) == XUI_OK && found == 1);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, 1, 0, &table) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, table, 1, &row) == XUI_OK);
    for (column = 0; column < 2; column++) {
        xui_doc_node_info_t info = {0}; info.iSize = sizeof(info);
        CHECK(xuiDocumentSnapshotGetChild(snapshot, row, column, &cell) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetNode(snapshot, cell, &info) == XUI_OK &&
            info.iSyntaxStart != UINT64_MAX && info.iSyntaxStart == info.iSyntaxEnd);
        position = match.tCaret; position.iKind = XUI_DOC_POSITION_GAP;
        position.iNodeId = cell; position.iOffset = 0;
        for (affinity = XUI_DOC_BEFORE; affinity <= XUI_DOC_AFTER; affinity++) {
            position.iAffinity = affinity;
            CHECK(xuiDocumentPositionToSource(snapshot, &position, &offset, &mapping) == XUI_OK &&
                mapping == XUI_DOC_MAP_SYNTAX && offset == info.iSyntaxStart);
            CHECK(xuiDocumentSourceToPositionEx(snapshot, offset, affinity, &reverse, &mapping) == XUI_OK &&
                mapping == XUI_DOC_MAP_SYNTAX && reverse.iNodeId == cell);
        }
    }
    CHECK(xuiDocumentSnapshotGetChild(snapshot, row, 0, &cell) == XUI_OK);
    xuiDocumentSnapshotRelease(snapshot);
    {
        xui_document_transaction txn;
        xui_doc_position_t caret = {0};
        match.tAnchor = match.tCaret = test_position(document, cell,
            XUI_DOC_POSITION_GAP, 0, XUI_DOC_AFTER);
        CHECK(xuiDocumentBeginTransaction(document, NULL, &txn) == XUI_OK);
        CHECK(xuiDocumentTxnReplaceRange(txn, &match, "new|cell", 8, &caret) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
        test_source(document, "| A | B |\r\n| - | - |\r\n|new\\|cell||\r\n", 1);
        CHECK(xuiDocumentUndo(document, NULL) == XUI_OK);
        test_source(document, text, 1);
    }
    xuiDocumentRelease(document);
    text = "| A | B | C |\n| - | - | - |\n| x | y |\n";
    CHECK(xuiDocumentCreate(&desc, &document) == XUI_OK);
    CHECK(xuiDocumentLoadMarkdown(document, text, strlen(text)) == XUI_OK);
    CHECK(xuiDocumentAcquireSnapshot(document, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, 1, 0, &table) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, table, 1, &row) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, row, 2, &cell) == XUI_OK);
    { xui_doc_node_info_t info = {0}; info.iSize = sizeof(info);
      CHECK(xuiDocumentSnapshotGetNode(snapshot, cell, &info) == XUI_OK &&
          info.iKind == XUI_DOC_CELL && info.iSyntaxStart == UINT64_MAX); }
    CHECK(xuiDocumentSnapshotFind(snapshot, XUI_DOC_SEMANTIC, "x", 1,
        NULL, &match, 1, &found) == XUI_OK && found == 1);
    position = match.tCaret; position.iKind = XUI_DOC_POSITION_GAP;
    position.iNodeId = cell; position.iOffset = 0; position.iAffinity = XUI_DOC_AFTER;
    CHECK(xuiDocumentPositionToSource(snapshot, &position, &offset, &mapping) == XUI_OK &&
        mapping == XUI_DOC_MAP_APPROXIMATE && offset <= strlen(text));
    CHECK(xuiDocumentSourceToPosition(snapshot, offset, &reverse, &mapping) == XUI_OK);
    xuiDocumentSnapshotRelease(snapshot);
    {
        xui_document_transaction txn;
        xui_doc_position_t caret = {0};
        match.tAnchor = match.tCaret = test_position(document, cell,
            XUI_DOC_POSITION_GAP, 0, XUI_DOC_AFTER);
        CHECK(xuiDocumentBeginTransaction(document, NULL, &txn) == XUI_OK);
        CHECK(xuiDocumentTxnReplaceRange(txn, &match, "new|cell", 8, &caret) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
        test_source(document,
            "| A | B | C |\n| - | - | - |\n| x | y | new\\|cell |\n", 1);
        CHECK(xuiDocumentUndo(document, NULL) == XUI_OK);
        test_source(document, text, 1);
    }
    xuiDocumentRelease(document);
    text = "lead\n\n| A | B |\n| - | - |\n|  |  |\n";
    CHECK(xuiDocumentCreate(&desc, &document) == XUI_OK);
    CHECK(xuiDocumentLoadMarkdown(document, text, strlen(text)) == XUI_OK);
    CHECK(xuiDocumentAcquireSnapshot(document, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, 1, 1, &table) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, table, 1, &row) == XUI_OK);
    CHECK(xuiDocumentSnapshotGetChild(snapshot, row, 0, &cell) == XUI_OK);
    { xui_doc_node_info_t info = {0}; xui_doc_txn_desc_t txn_desc = {0};
      xui_document_transaction txn; xui_document_snapshot updated;
      uint64_t original;
      info.iSize = sizeof(info); txn_desc.iSize = sizeof(txn_desc);
      txn_desc.iDomain = XUI_DOC_SOURCE;
      CHECK(xuiDocumentSnapshotGetNode(snapshot, cell, &info) == XUI_OK &&
          info.iSyntaxStart != UINT64_MAX && info.iSyntaxStart == info.iSyntaxEnd);
      original = info.iSyntaxStart;
      CHECK(xuiDocumentBeginTransaction(document, &txn_desc, &txn) == XUI_OK);
      CHECK(xuiDocumentTxnReplaceSource(txn, 0, 0, "XX", 2) == XUI_OK);
      CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
      CHECK(xuiDocumentAcquireSnapshot(document, &updated) == XUI_OK);
      CHECK(xuiDocumentSnapshotGetNode(updated, cell, &info) == XUI_OK &&
          info.iSyntaxStart == original + 2 && info.iSyntaxEnd == original + 2);
      for (affinity = XUI_DOC_BEFORE; affinity <= XUI_DOC_AFTER; affinity++) {
          CHECK(xuiDocumentSourceToPositionEx(updated, original + 2, affinity,
              &reverse, &mapping) == XUI_OK && mapping == XUI_DOC_MAP_SYNTAX &&
              reverse.iNodeId == cell && reverse.iKind == XUI_DOC_POSITION_GAP);
          CHECK(xuiDocumentPositionToSource(updated, &reverse, &offset, &mapping) == XUI_OK &&
              offset == original + 2 && mapping == XUI_DOC_MAP_SYNTAX);
          CHECK(xuiDocumentSourceToPositionEx(snapshot, original, affinity,
              &reverse, &mapping) == XUI_OK && mapping == XUI_DOC_MAP_SYNTAX &&
              reverse.iNodeId == cell);
      }
      xuiDocumentSnapshotRelease(updated);
      CHECK(xuiDocumentUndo(document, NULL) == XUI_OK);
      CHECK(xuiDocumentAcquireSnapshot(document, &updated) == XUI_OK);
      CHECK(xuiDocumentSnapshotGetNode(updated, cell, &info) == XUI_OK && info.iSyntaxStart == original);
      xuiDocumentSnapshotRelease(updated); }
    xuiDocumentSnapshotRelease(snapshot); xuiDocumentRelease(document);
    puts("Markdown empty table cells: explicit syntax anchors round-trip; omitted cells stay approximate");
}
static void markdown_omitted_cell_edit_cases(void)
{
    static const struct {
        const char* original;
        const char* updated;
        uint64_t column;
    } cases[] = {
        {"| A | B | C |\n| - | - | - |\n| x | y |\n",
         "| A | B | C |\n| - | - | - |\n| x | y | new\\|cell |\n", 2},
        {"| A | B | C\n| - | - | -\n| x | y\n",
         "| A | B | C\n| - | - | -\n| x | y | new\\|cell\n", 2},
        {"| A | B | C | D |\r\n| - | - | - | - |\r\n| x | y |\r\n",
         "| A | B | C | D |\r\n| - | - | - | - |\r\n| x | y | | new\\|cell |\r\n", 3},
        {"| A | B | C |\r\n| - | - | - |\r\n| x | y |  \r\n",
         "| A | B | C |\r\n| - | - | - |\r\n| x | y | new\\|cell |  \r\n", 2},
        {"> | A | B | C |\n> | - | - | - |\n> | x | y |\n",
         "> | A | B | C |\n> | - | - | - |\n> | x | y | new\\|cell |\n", 2},
        {"| A | B | C |\n| - | - | - |\n| x | y\\|\n",
         "| A | B | C |\n| - | - | - |\n| x | y\\| | new\\|cell\n", 2}
    };
    size_t i;
    for (i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        xui_document document = test_markdown_open(cases[i].original);
        xui_document_snapshot snapshot;
        xui_document_transaction txn;
        xui_doc_node_id table, row, cell;
        xui_doc_node_info_t info = {0};
        xui_doc_range_t range;
        xui_doc_position_t caret = {0};
        uint64_t found = 0;
        CHECK(xuiDocumentAcquireSnapshot(document, &snapshot) == XUI_OK);
        table = find_kind(snapshot, XUI_DOCUMENT_ROOT, XUI_DOC_TABLE);
        CHECK(table != 0);
        CHECK(xuiDocumentSnapshotGetChild(snapshot, table, 1, &row) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetChild(snapshot, row, cases[i].column, &cell) == XUI_OK);
        info.iSize = sizeof(info);
        CHECK(xuiDocumentSnapshotGetNode(snapshot, cell, &info) == XUI_OK &&
            info.iKind == XUI_DOC_CELL && info.iSyntaxStart == UINT64_MAX);
        xuiDocumentSnapshotRelease(snapshot);
        range.tAnchor = range.tCaret = test_position(document, cell,
            XUI_DOC_POSITION_GAP, 0, XUI_DOC_AFTER);
        CHECK(xuiDocumentBeginTransaction(document, NULL, &txn) == XUI_OK);
        CHECK(xuiDocumentTxnReplaceRange(txn, &range, "new|cell", 8, &caret) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
        test_source(document, cases[i].updated, 1);
        CHECK(xuiDocumentAcquireSnapshot(document, &snapshot) == XUI_OK);
        table = find_kind(snapshot, XUI_DOCUMENT_ROOT, XUI_DOC_TABLE);
        CHECK(table != 0);
        CHECK(xuiDocumentSnapshotGetChild(snapshot, table, 1, &row) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetChild(snapshot, row, cases[i].column, &cell) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetNode(snapshot, cell, &info) == XUI_OK &&
            info.iSyntaxStart != UINT64_MAX);
        CHECK(xuiDocumentSnapshotFind(snapshot, XUI_DOC_SEMANTIC, "new|cell", 8,
            NULL, NULL, 0, &found) == XUI_OK && found == 1);
        xuiDocumentSnapshotRelease(snapshot);
        CHECK(xuiDocumentUndo(document, NULL) == XUI_OK);
        test_source(document, cases[i].original, 1);
        CHECK(xuiDocumentRedo(document, NULL) == XUI_OK);
        test_source(document, cases[i].updated, 1);
        xuiDocumentRelease(document);
    }
    {
        static const char prefix[] = "| A | B | C |\r\n| - | - | - |\r\n| x | y |";
        static const char insertion[] = " new\\|cell |";
        const size_t spaces = 8192, head = sizeof(prefix) - 1;
        char *original = malloc(head + spaces + 3);
        char *updated = malloc(head + sizeof(insertion) - 1 + spaces + 3);
        xui_document document;
        xui_document_snapshot snapshot;
        xui_document_transaction txn;
        xui_doc_node_id table, row, cell;
        xui_doc_range_t range;
        xui_doc_position_t caret = {0};
        CHECK(original && updated);
        memcpy(original, prefix, head); memset(original + head, ' ', spaces);
        memcpy(original + head + spaces, "\r\n", 3);
        memcpy(updated, prefix, head);
        memcpy(updated + head, insertion, sizeof(insertion) - 1);
        memset(updated + head + sizeof(insertion) - 1, ' ', spaces);
        memcpy(updated + head + sizeof(insertion) - 1 + spaces, "\r\n", 3);
        document = test_markdown_open(original);
        CHECK(xuiDocumentAcquireSnapshot(document, &snapshot) == XUI_OK);
        table = find_kind(snapshot, XUI_DOCUMENT_ROOT, XUI_DOC_TABLE);
        CHECK(table != 0);
        CHECK(xuiDocumentSnapshotGetChild(snapshot, table, 1, &row) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetChild(snapshot, row, 2, &cell) == XUI_OK);
        xuiDocumentSnapshotRelease(snapshot);
        range.tAnchor = range.tCaret = test_position(document, cell,
            XUI_DOC_POSITION_GAP, 0, XUI_DOC_AFTER);
        CHECK(xuiDocumentBeginTransaction(document, NULL, &txn) == XUI_OK);
        CHECK(xuiDocumentTxnReplaceRange(txn, &range, "new|cell", 8, &caret) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
        test_source(document, updated, 1);
        CHECK(xuiDocumentUndo(document, NULL) == XUI_OK);
        test_source(document, original, 1);
        xuiDocumentRelease(document); free(original); free(updated);
    }
    puts("Markdown omitted table cells: row-local source insertion, escaped pipes, multi-column gaps, CRLF, quote, long trailing whitespace and Undo/Redo passed");
}
static void markdown_empty_cell_edit_failures(void)
{
    static const char* originals[] = {
        "| A | B |\r\n| - | - |\r\n|   |   |\r\n",
        "| A | B | C |\r\n| - | - | - |\r\n| x | y |\r\n"
    };
    static const char* updated[] = {
        "| A | B |\r\n| - | - |\r\n|   new\\|cell|   |\r\n",
        "| A | B | C |\r\n| - | - | - |\r\n| x | y | new\\|cell |\r\n"
    };
    long point;
    unsigned mode;
    for (mode = 0; mode < 2; mode++) {
      const char* original = originals[mode];
      int succeeded = 0;
      for (point = 0; point < 1024 && !succeeded; point++) {
        fail_allocator allocator = {-1, 0};
        xui_doc_desc_t desc = {0};
        xui_document document = NULL;
        xui_document_snapshot before = NULL, after = NULL;
        xui_document_transaction txn = NULL;
        xui_doc_node_id table, row, cell;
        xui_doc_range_t range;
        xui_doc_position_t caret = {0};
        uint64_t revision;
        int result, can_undo;
        desc.iSize = sizeof(desc); desc.iProfile = XUI_DOCUMENT_MARKDOWN;
        desc.iMarkdownDialect = XUI_MD_GFM;
        desc.onAlloc = failing_alloc; desc.onFree = failing_free;
        desc.pAllocatorUser = &allocator;
        CHECK(xuiDocumentCreate(&desc, &document) == XUI_OK);
        CHECK(xuiDocumentLoadMarkdown(document, original, strlen(original)) == XUI_OK);
        CHECK(xuiDocumentAcquireSnapshot(document, &before) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetChild(before, XUI_DOCUMENT_ROOT, 0, &table) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetChild(before, table, 1, &row) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetChild(before, row, mode ? 2 : 0, &cell) == XUI_OK);
        range.tAnchor = range.tCaret = test_position(document, cell,
            XUI_DOC_POSITION_GAP, 0, XUI_DOC_AFTER);
        revision = xuiDocumentGetRevision(document);
        can_undo = xuiDocumentCanUndo(document);
        allocator.remaining = point;
        result = xuiDocumentBeginTransaction(document, NULL, &txn);
        if (result == XUI_OK) result = xuiDocumentTxnReplaceRange(txn,
            &range, "new|cell", 8, &caret);
        if (result == XUI_OK) result = xuiDocumentTxnCommit(txn, NULL);
        if (txn) xuiDocumentTxnRelease(txn);
        allocator.remaining = -1;
        if (result == XUI_OK) {
            succeeded = 1;
            test_source(document, updated[mode], 1);
            CHECK(xuiDocumentUndo(document, NULL) == XUI_OK);
            test_source(document, original, 1);
        } else {
            CHECK(result == XUI_ERROR_OUT_OF_MEMORY &&
                xuiDocumentGetRevision(document) == revision &&
                xuiDocumentCanUndo(document) == can_undo);
            test_source(document, original, 1);
            CHECK(xuiDocumentAcquireSnapshot(document, &after) == XUI_OK);
            expect_identity_tree(before, after, XUI_DOCUMENT_ROOT);
            expect_same_syntax(before, after);
            xuiDocumentSnapshotRelease(after);
        }
        xuiDocumentSnapshotRelease(before); xuiDocumentRelease(document);
        CHECK(allocator.live == 0);
      }
      CHECK(succeeded);
      printf("Markdown %s empty-cell source edit allocation-failure sweep: %ld points; atomic source/tree/history and no leaks passed\n",
          mode ? "omitted" : "explicit", point);
    }
}
static void rich_markdown_conversion_cases(void)
{
    xui_document rich, markdown = NULL;
    xui_document_transaction txn;
    xui_document_snapshot snapshot, converted;
    xui_doc_attributes_t attrs = {0};
    xui_doc_markdown_loss_t losses[8] = {{0}};
    uint64_t paragraph, first, bold, second, target_text, count, bytes;
    uint64_t table, row, cell;
    char source[256];
    CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    paragraph = insert(txn, 1, XUI_DOC_PARAGRAPH, NULL);
    first = insert(txn, paragraph, XUI_DOC_TEXT, "Hello ");
    bold = insert(txn, paragraph, XUI_DOC_TEXT, "world");
    attrs.iMarks = XUI_DOC_BOLD;
    CHECK(xuiDocumentTxnSetAttributes(txn, bold, &attrs) == XUI_OK);
    second = insert(txn, 1, XUI_DOC_PARAGRAPH, NULL);
    insert(txn, second, XUI_DOC_TEXT, "Next");
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK);
    xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    xuiDocumentRelease(rich); /* The retained snapshot owns conversion input. */
    count = UINT64_MAX;
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_COMMONMARK,
        NULL, 0, &count) == XUI_OK && count == 0);
    CHECK(xuiDocumentSnapshotConvertToMarkdown(snapshot, XUI_MD_COMMONMARK,
        &markdown) == XUI_OK && markdown && !xuiDocumentIsDirty(markdown));
    CHECK(xuiDocumentGetProfile(markdown) == XUI_DOCUMENT_MARKDOWN);
    CHECK(xuiDocumentAcquireSnapshot(markdown, &converted) == XUI_OK);
    CHECK(xuiDocumentSnapshotCopySource(converted, source, sizeof(source), &bytes) == XUI_OK &&
        strstr(source, "Hello **world**") && strstr(source, "Next"));
    target_text = find_kind(converted, 1, XUI_DOC_TEXT);
    xuiDocumentSnapshotRelease(converted);
    CHECK(xuiDocumentBeginTransaction(markdown, NULL, &txn) == XUI_OK);
    CHECK(xuiDocumentTxnReplaceText(txn, target_text, 0, 5, "Hi", 2) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK);
    xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentUndo(markdown, NULL) == XUI_OK && !xuiDocumentIsDirty(markdown));
    xuiDocumentRelease(markdown); xuiDocumentSnapshotRelease(snapshot);

    CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    paragraph = insert(txn, 1, XUI_DOC_PARAGRAPH, NULL);
    first = insert(txn, paragraph, XUI_DOC_TEXT, "red");
    bold = insert(txn, paragraph, XUI_DOC_TEXT, "underlined");
    attrs = (xui_doc_attributes_t){0}; attrs.iAlignment = 1;
    CHECK(xuiDocumentTxnSetAttributes(txn, paragraph, &attrs) == XUI_OK);
    attrs = (xui_doc_attributes_t){0}; attrs.iTextColor = 0xff0000ff;
    CHECK(xuiDocumentTxnSetAttributes(txn, first, &attrs) == XUI_OK);
    attrs = (xui_doc_attributes_t){0}; attrs.iMarks = XUI_DOC_UNDERLINE;
    CHECK(xuiDocumentTxnSetAttributes(txn, bold, &attrs) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK);
    xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_GFM,
        NULL, 0, &count) == XUI_OK && count == 3);
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_GFM,
        losses, 2, &count) == XUI_ERROR_BUFFER_TOO_SMALL && count == 3);
    CHECK(losses[0].iNodeId == paragraph && (losses[0].iReasons & XUI_DOC_MD_LOSS_BLOCK_STYLE));
    CHECK(losses[1].iNodeId == first && (losses[1].iReasons & XUI_DOC_MD_LOSS_TEXT_STYLE));
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_GFM,
        losses, 8, &count) == XUI_OK && count == 3);
    CHECK(losses[2].iNodeId == bold && (losses[2].iReasons & XUI_DOC_MD_LOSS_MARK));
    markdown = (xui_document)(uintptr_t)1;
    CHECK(xuiDocumentSnapshotConvertToMarkdown(snapshot, XUI_MD_GFM,
        &markdown) == XUI_DOC_ERROR_UNREPRESENTABLE && markdown == NULL);
    CHECK(xuiDocumentSnapshotConvertToMarkdownWithPolicy(snapshot, XUI_MD_GFM,
        XUI_DOC_MD_LOSS_TEXT_STYLE | XUI_DOC_MD_LOSS_BLOCK_STYLE,
        &markdown) == XUI_DOC_ERROR_UNREPRESENTABLE && markdown == NULL);
    CHECK(xuiDocumentSnapshotConvertToMarkdownWithPolicy(snapshot, XUI_MD_GFM,
        XUI_DOC_MD_LOSS_NODE, &markdown) == XUI_ERROR_INVALID_ARGUMENT && markdown == NULL);
    CHECK(xuiDocumentSnapshotConvertToMarkdownWithPolicy(snapshot, XUI_MD_GFM,
        XUI_DOC_MD_LOSS_MARK | XUI_DOC_MD_LOSS_TEXT_STYLE | XUI_DOC_MD_LOSS_BLOCK_STYLE,
        &markdown) == XUI_OK && markdown && !xuiDocumentIsDirty(markdown));
    CHECK(xuiDocumentAcquireSnapshot(markdown, &converted) == XUI_OK);
    CHECK(xuiDocumentSnapshotCopySource(converted, source, sizeof(source), &bytes) == XUI_OK &&
        strstr(source, "redunderlined") && !strstr(source, "<span"));
    xuiDocumentSnapshotRelease(converted); xuiDocumentRelease(markdown); markdown = NULL;
    { xui_doc_node_info_t info = {0}; info.iSize = sizeof(info);
      CHECK(xuiDocumentSnapshotGetNode(snapshot, first, &info) == XUI_OK &&
          info.tAttributes.iTextColor == 0xff0000ff); }
    xuiDocumentSnapshotRelease(snapshot); xuiDocumentRelease(rich);

    CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    paragraph = insert(txn, 1, XUI_DOC_PARAGRAPH, NULL);
    insert(txn, paragraph, XUI_DOC_TEXT, "a\nb");
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK);
    xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_EXTENDED,
        losses, 8, &count) == XUI_OK && count == 1 &&
        losses[0].iNodeId == 1 && losses[0].iReasons == XUI_DOC_MD_LOSS_ROUNDTRIP);
    CHECK(xuiDocumentSnapshotConvertToMarkdown(snapshot, XUI_MD_EXTENDED,
        &markdown) == XUI_DOC_ERROR_UNREPRESENTABLE && markdown == NULL);
    CHECK(xuiDocumentSnapshotConvertToMarkdownWithPolicy(snapshot, XUI_MD_EXTENDED,
        XUI_DOC_MD_LOSS_MARK | XUI_DOC_MD_LOSS_TEXT_STYLE,
        &markdown) == XUI_DOC_ERROR_UNREPRESENTABLE && markdown == NULL);
    xuiDocumentSnapshotRelease(snapshot); xuiDocumentRelease(rich);

    CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    paragraph = insert(txn, 1, XUI_DOC_PARAGRAPH, NULL);
    first = insert(txn, paragraph, XUI_DOC_TEXT, "strike");
    attrs = (xui_doc_attributes_t){0}; attrs.iMarks = XUI_DOC_STRIKE;
    CHECK(xuiDocumentTxnSetAttributes(txn, first, &attrs) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_COMMONMARK,
        losses, 8, &count) == XUI_OK && count == 1 &&
        losses[0].iNodeId == first && (losses[0].iReasons & XUI_DOC_MD_LOSS_MARK));
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_GFM,
        losses, 8, &count) == XUI_OK && count == 0);
    CHECK(xuiDocumentSnapshotConvertToMarkdown(snapshot, XUI_MD_GFM,
        &markdown) == XUI_OK && markdown);
    CHECK(xuiDocumentAcquireSnapshot(markdown, &converted) == XUI_OK);
    CHECK(xuiDocumentSnapshotCopySource(converted, source, sizeof(source), &bytes) == XUI_OK &&
        strstr(source, "~~strike~~"));
    xuiDocumentSnapshotRelease(converted); xuiDocumentRelease(markdown);
    markdown = NULL; xuiDocumentSnapshotRelease(snapshot); xuiDocumentRelease(rich);

    CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    table = insert(txn, 1, XUI_DOC_TABLE, NULL);
    row = insert(txn, table, XUI_DOC_ROW, NULL);
    cell = insert(txn, row, XUI_DOC_CELL, NULL);
    attrs = (xui_doc_attributes_t){0}; attrs.iFlags = XUI_DOC_HEADER;
    CHECK(xuiDocumentTxnSetAttributes(txn, cell, &attrs) == XUI_OK);
    paragraph = insert(txn, cell, XUI_DOC_PARAGRAPH, NULL);
    insert(txn, paragraph, XUI_DOC_TEXT, "Head");
    row = insert(txn, table, XUI_DOC_ROW, NULL);
    cell = insert(txn, row, XUI_DOC_CELL, NULL);
    paragraph = insert(txn, cell, XUI_DOC_PARAGRAPH, NULL);
    target_text = insert(txn, paragraph, XUI_DOC_TEXT, "Body");
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_GFM,
        losses, 8, &count) == XUI_OK && count == 0);
    CHECK(xuiDocumentSnapshotConvertToMarkdown(snapshot, XUI_MD_GFM,
        &markdown) == XUI_OK && markdown);
    xuiDocumentRelease(markdown); markdown = NULL; xuiDocumentSnapshotRelease(snapshot);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    CHECK(xuiDocumentTxnSetTableColumnWidth(txn, table, 0, 120) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_GFM,
        losses, 8, &count) == XUI_OK && count == 1 &&
        losses[0].iNodeId == table && (losses[0].iReasons & XUI_DOC_MD_LOSS_GEOMETRY));
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_COMMONMARK,
        losses, 8, &count) == XUI_OK && count >= 1 &&
        (losses[0].iReasons & XUI_DOC_MD_LOSS_DIALECT));
    CHECK(xuiDocumentSnapshotConvertToMarkdown(snapshot, XUI_MD_GFM,
        &markdown) == XUI_DOC_ERROR_UNREPRESENTABLE && markdown == NULL);
    CHECK(xuiDocumentSnapshotConvertToMarkdownWithPolicy(snapshot, XUI_MD_GFM,
        XUI_DOC_MD_LOSS_GEOMETRY, &markdown) == XUI_OK && markdown);
    CHECK(xuiDocumentAcquireSnapshot(markdown, &converted) == XUI_OK);
    CHECK(xuiDocumentSnapshotCopySource(converted, source, sizeof(source), &bytes) == XUI_OK &&
        strstr(source, "| Head |") && strstr(source, "| Body |"));
    xuiDocumentSnapshotRelease(converted); xuiDocumentRelease(markdown); markdown = NULL;
    xuiDocumentSnapshotRelease(snapshot);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    CHECK(xuiDocumentTxnSetTableColumnWidth(txn, table, 0, 0) == XUI_OK);
    CHECK(xuiDocumentTxnReplaceText(txn, target_text, 0, 4, "Body\nExtra", 10) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_GFM,
        losses, 8, &count) == XUI_OK && count <= 8);
    { uint64_t i; int found = 0;
      for (i = 0; i < count; i++)
          if (losses[i].iNodeId == cell && (losses[i].iReasons & XUI_DOC_MD_LOSS_TABLE_CONTENT)) found = 1;
      CHECK(found); }
    CHECK(xuiDocumentSnapshotConvertToMarkdownWithPolicy(snapshot, XUI_MD_GFM,
        XUI_DOC_MD_LOSS_GEOMETRY, &markdown) == XUI_DOC_ERROR_UNREPRESENTABLE && markdown == NULL);
    xuiDocumentSnapshotRelease(snapshot); xuiDocumentRelease(rich);

    CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    table = insert(txn, 1, XUI_DOC_TABLE, NULL);
    row = insert(txn, table, XUI_DOC_ROW, NULL);
    cell = insert(txn, row, XUI_DOC_CELL, NULL);
    attrs = (xui_doc_attributes_t){0}; attrs.iFlags = XUI_DOC_HEADER; attrs.iColumnSpan = 2;
    CHECK(xuiDocumentTxnSetAttributes(txn, cell, &attrs) == XUI_OK);
    paragraph = insert(txn, cell, XUI_DOC_PARAGRAPH, NULL);
    insert(txn, paragraph, XUI_DOC_TEXT, "Header");
    row = insert(txn, table, XUI_DOC_ROW, NULL);
    cell = insert(txn, row, XUI_DOC_CELL, NULL);
    paragraph = insert(txn, cell, XUI_DOC_PARAGRAPH, NULL);
    insert(txn, paragraph, XUI_DOC_TEXT, "left");
    cell = insert(txn, row, XUI_DOC_CELL, NULL);
    paragraph = insert(txn, cell, XUI_DOC_PARAGRAPH, NULL);
    insert(txn, paragraph, XUI_DOC_TEXT, "right");
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotConvertToMarkdownWithPolicy(snapshot, XUI_MD_GFM,
        XUI_DOC_MD_LOSS_GEOMETRY, &markdown) == XUI_DOC_ERROR_UNREPRESENTABLE && markdown == NULL);
    xuiDocumentSnapshotRelease(snapshot); xuiDocumentRelease(rich);

    CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    paragraph = insert(txn, 1, XUI_DOC_PARAGRAPH, NULL);
    first = insert(txn, paragraph, XUI_DOC_IMAGE, "alt");
    attrs = (xui_doc_attributes_t){0}; attrs.fWidth = 120; attrs.fHeight = 80;
    CHECK(xuiDocumentTxnSetAttributes(txn, first, &attrs) == XUI_OK);
    CHECK(xuiDocumentTxnSetResource(txn, first, "/image.png", "", "") == XUI_OK);
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_GFM,
        losses, 8, &count) == XUI_OK && count == 1 &&
        losses[0].iNodeId == first && (losses[0].iReasons & XUI_DOC_MD_LOSS_GEOMETRY));
    CHECK(xuiDocumentSnapshotConvertToMarkdownWithPolicy(snapshot, XUI_MD_GFM,
        XUI_DOC_MD_LOSS_GEOMETRY, &markdown) == XUI_OK && markdown);
    CHECK(xuiDocumentAcquireSnapshot(markdown, &converted) == XUI_OK);
    CHECK(xuiDocumentSnapshotCopySource(converted, source, sizeof(source), &bytes) == XUI_OK &&
        strstr(source, "![alt]"));
    { xui_doc_node_info_t info = {0}; info.iSize = sizeof(info);
      CHECK(xuiDocumentSnapshotGetNode(converted, find_kind(converted, 1, XUI_DOC_IMAGE),
          &info) == XUI_OK && !strcmp(info.sResource, "/image.png") &&
          info.tAttributes.fWidth == 0 && info.tAttributes.fHeight == 0); }
    xuiDocumentSnapshotRelease(converted); xuiDocumentRelease(markdown);
    markdown = NULL; xuiDocumentSnapshotRelease(snapshot); xuiDocumentRelease(rich);

    CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    first = insert(txn, 1, XUI_DOC_HTML, "<div>ok</div>\n");
    attrs = (xui_doc_attributes_t){0}; attrs.iFlags = XUI_DOC_BLOCK;
    CHECK(xuiDocumentTxnSetAttributes(txn, first, &attrs) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
    CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, XUI_MD_COMMONMARK,
        losses, 8, &count) == XUI_OK && count == 0);
    CHECK(xuiDocumentSnapshotConvertToMarkdown(snapshot, XUI_MD_COMMONMARK,
        &markdown) == XUI_OK && markdown);
    xuiDocumentRelease(markdown); xuiDocumentSnapshotRelease(snapshot); xuiDocumentRelease(rich);
    puts("Rich to Markdown: loss inventory, strict/approved-presentation conversion and round-trip refusal passed");
}
static void rich_markdown_boundary_conversion(void)
{
    const struct {
        const char* text[5]; uint32_t marks[5]; const char* source; uint32_t dialect;
    } cases[] = {
        {{"alpha", " beta", NULL}, {0, XUI_DOC_BOLD, 0}, "alph&#97;**&#32;beta**", XUI_MD_COMMONMARK},
        {{"alpha ", "beta", NULL}, {XUI_DOC_BOLD, 0, 0}, "**alpha&#32;**&#98;eta", XUI_MD_COMMONMARK},
        {{"alpha ", "beta", " gamma"}, {XUI_DOC_BOLD, 0, XUI_DOC_BOLD},
            "**alpha&#32;**&#98;et&#97;__&#32;gamma__", XUI_MD_COMMONMARK},
        {{" alpha", NULL, NULL}, {XUI_DOC_BOLD, 0, 0}, "**&#32;alpha**", XUI_MD_COMMONMARK},
        {{"alpha ", NULL, NULL}, {XUI_DOC_BOLD, 0, 0}, "**alpha&#32;**", XUI_MD_COMMONMARK},
        {{"caf\xc3\xa9", " \xce\xb2" "eta", NULL}, {0, XUI_DOC_BOLD, 0},
            "caf&#233;**&#32;\xce\xb2" "eta**", XUI_MD_COMMONMARK},
        {{"\xce\xb1 ", "\xce\xb2" "eta", NULL}, {XUI_DOC_BOLD, 0, 0},
            "**\xce\xb1&#32;**&#946;eta", XUI_MD_COMMONMARK},
        {{"alpha ", "be", "ta", " gamma", NULL}, {XUI_DOC_BOLD, 0, 0, XUI_DOC_BOLD, 0},
            "**alpha&#32;**&#98;et&#97;__&#32;gamma__", XUI_MD_COMMONMARK},
        {{"a ", "b", " c ", "d", " e"}, {XUI_DOC_BOLD, 0, XUI_DOC_BOLD, 0, XUI_DOC_BOLD},
            "**a&#32;**&#98;__&#32;c&#32;__&#100;**&#32;e**", XUI_MD_COMMONMARK},
        {{"alpha", " beta", NULL}, {0, XUI_DOC_ITALIC, 0}, "alph&#97;*&#32;beta*", XUI_MD_COMMONMARK},
        {{"alpha ", "beta", NULL}, {XUI_DOC_ITALIC, 0, 0}, "*alpha&#32;*&#98;eta", XUI_MD_COMMONMARK},
        {{" alpha", NULL, NULL}, {XUI_DOC_ITALIC, 0, 0}, "*&#32;alpha*", XUI_MD_COMMONMARK},
        {{"alpha ", NULL, NULL}, {XUI_DOC_ITALIC, 0, 0}, "*alpha&#32;*", XUI_MD_COMMONMARK},
        {{"alpha ", "beta", " gamma"}, {XUI_DOC_ITALIC, 0, XUI_DOC_ITALIC},
            "*alpha&#32;*&#98;et&#97;*&#32;gamma*", XUI_MD_COMMONMARK},
        {{"a ", "b", " c ", "d", " e"}, {XUI_DOC_ITALIC, 0, XUI_DOC_ITALIC, 0, XUI_DOC_ITALIC},
            "*a&#32;*&#98;*&#32;c&#32;*&#100;*&#32;e*", XUI_MD_COMMONMARK},
        {{"alpha", " beta", NULL}, {0, XUI_DOC_STRIKE, 0}, "alph&#97;~~&#32;beta~~", XUI_MD_GFM},
        {{"alpha ", "beta", NULL}, {XUI_DOC_STRIKE, 0, 0}, "~~alpha&#32;~~&#98;eta", XUI_MD_GFM},
        {{"alpha ", "beta", " gamma"}, {XUI_DOC_STRIKE, 0, XUI_DOC_STRIKE},
            "~~alpha&#32;~~&#98;et&#97;~~&#32;gamma~~", XUI_MD_GFM},
        {{"alpha", " beta", NULL}, {0, XUI_DOC_HIGHLIGHT, 0}, "alph&#97;==&#32;beta==", XUI_MD_EXTENDED},
        {{"alpha ", "beta", NULL}, {XUI_DOC_HIGHLIGHT, 0, 0}, "==alpha&#32;==&#98;eta", XUI_MD_EXTENDED},
        {{"alpha ", "beta", " gamma"}, {XUI_DOC_HIGHLIGHT, 0, XUI_DOC_HIGHLIGHT},
            "==alpha&#32;==&#98;et&#97;==&#32;gamma==", XUI_MD_EXTENDED},
        {{"alpha", " beta", NULL}, {0, XUI_DOC_SUBSCRIPT, 0}, "alph&#97;~&#32;beta~", XUI_MD_EXTENDED},
        {{"alpha ", "beta", NULL}, {XUI_DOC_SUBSCRIPT, 0, 0}, "~alpha&#32;~&#98;eta", XUI_MD_EXTENDED},
        {{"alpha ", "beta", " gamma"}, {XUI_DOC_SUBSCRIPT, 0, XUI_DOC_SUBSCRIPT},
            "~alpha&#32;~&#98;et&#97;~&#32;gamma~", XUI_MD_EXTENDED},
        {{"alpha", " beta", NULL}, {0, XUI_DOC_SUPERSCRIPT, 0}, "alph&#97;^&#32;beta^", XUI_MD_EXTENDED},
        {{"alpha ", "beta", NULL}, {XUI_DOC_SUPERSCRIPT, 0, 0}, "^alpha&#32;^&#98;eta", XUI_MD_EXTENDED},
        {{"alpha ", "beta", " gamma"}, {XUI_DOC_SUPERSCRIPT, 0, XUI_DOC_SUPERSCRIPT},
            "^alpha&#32;^&#98;et&#97;^&#32;gamma^", XUI_MD_EXTENDED},
        {{"alpha ", "beta", " gamma"}, {XUI_DOC_BOLD, 0, XUI_DOC_ITALIC},
            "**alpha&#32;**&#98;et&#97;*&#32;gamma*", XUI_MD_COMMONMARK},
        {{"alpha ", " beta", NULL}, {XUI_DOC_BOLD, XUI_DOC_ITALIC, 0},
            "**alpha&#32;**_&#32;beta_", XUI_MD_COMMONMARK},
        {{"alpha ", " beta", NULL}, {XUI_DOC_STRIKE, XUI_DOC_HIGHLIGHT, 0},
            "~~alpha&#32;~~==&#32;beta==", XUI_MD_EXTENDED},
        {{"alpha ", " beta", NULL}, {XUI_DOC_SUBSCRIPT, XUI_DOC_SUPERSCRIPT, 0},
            "~alpha&#32;~^&#32;beta^", XUI_MD_EXTENDED},
        {{"alpha & ", "beta", " gamma"}, {XUI_DOC_BOLD | XUI_DOC_ITALIC, XUI_DOC_BOLD,
            XUI_DOC_BOLD | XUI_DOC_ITALIC}, "**_", XUI_MD_COMMONMARK},
        {{"alpha & ", "beta", " gamma"}, {XUI_DOC_BOLD | XUI_DOC_ITALIC, XUI_DOC_ITALIC,
            XUI_DOC_BOLD | XUI_DOC_ITALIC}, "*__", XUI_MD_COMMONMARK},
        {{"alpha", "beta", "gamma"}, {XUI_DOC_BOLD | XUI_DOC_ITALIC, XUI_DOC_BOLD,
            XUI_DOC_BOLD | XUI_DOC_ITALIC}, "**_", XUI_MD_COMMONMARK},
        {{"al", "pha & ", "be", "ta", " gamma"}, {XUI_DOC_BOLD | XUI_DOC_ITALIC,
            XUI_DOC_BOLD | XUI_DOC_ITALIC, XUI_DOC_BOLD, XUI_DOC_BOLD,
            XUI_DOC_BOLD | XUI_DOC_ITALIC}, "**_", XUI_MD_COMMONMARK}
    };
    unsigned i, j;
    for (i = 0; i < sizeof(cases) / sizeof(*cases); i++) {
        xui_document rich, markdown = NULL; xui_document_transaction t;
        xui_document_snapshot snapshot, converted; xui_doc_attributes_t attrs = {0};
        uint64_t paragraph, id, count, bytes; char source[256];
        CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK && xuiDocumentBeginTransaction(rich, NULL, &t) == XUI_OK);
        paragraph = insert(t, 1, XUI_DOC_PARAGRAPH, NULL);
        for (j = 0; j < 5 && cases[i].text[j]; j++) {
            id = insert(t, paragraph, XUI_DOC_TEXT, cases[i].text[j]);
            if (cases[i].marks[j]) {
                attrs.iMarks = cases[i].marks[j];
                CHECK(xuiDocumentTxnSetAttributes(t, id, &attrs) == XUI_OK);
            }
        }
        CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
        CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
        CHECK(xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot, cases[i].dialect,
            NULL, 0, &count) == XUI_OK && count == 0);
        CHECK(xuiDocumentSnapshotConvertToMarkdown(snapshot, cases[i].dialect, &markdown) == XUI_OK && markdown);
        CHECK(xuiDocumentAcquireSnapshot(markdown, &converted) == XUI_OK);
        CHECK(xuiDocumentSnapshotCopySource(converted, source, sizeof(source), &bytes) == XUI_OK);
        if (strstr(source, cases[i].source) != source)
            fprintf(stderr, "Boundary case %u: expected prefix [%s], got [%s]\n",
                i, cases[i].source, source);
        CHECK(strstr(source, cases[i].source) == source);
        xuiDocumentSnapshotRelease(converted); xuiDocumentRelease(markdown);
        xuiDocumentSnapshotRelease(snapshot); xuiDocumentRelease(rich);
    }
    puts("Rich to Markdown: marked whitespace and adjacent text boundaries round-trip without loss");
}
static void rich_markdown_adjacent_mark_transitions(void)
{
    static const char* words[][6] = {
        {"a ", "b ", "c ", "d", "e", "f"},
        {"a ", "b", " c", " d", "e", "f"},
        {"a", "b", "c", "d", "e", "f"},
        {"a.", "b", "c"},
        {"a", ".b", "c"},
        {"a", "b.", "c"},
        {"a", "b", ".c"},
        {"(", "x", ")"},
        {"你", "好", "啊"},
        {"a", "*", "b"},
        {"a", "_", "b"},
        {"a", "&", "b"},
        {"a。", "b", "c"},
        {"a", "。b", "c"},
        {"a", "b。", "c"},
        {"a", "b", "。c"},
        {"「", "x", "」"},
        {"a\xc2\xa0", "b", "c"},
        {"a", "\xc2\xa0" "b", "c"},
        {"a", "b\xc2\xa0", "c"},
        {"a", "b", "\xc2\xa0" "c"}
    };
    static const uint32_t marks[] = {0, XUI_DOC_BOLD, XUI_DOC_ITALIC,
        XUI_DOC_BOLD | XUI_DOC_ITALIC};
    static const uint32_t dialects[] = {
        XUI_MD_COMMONMARK, XUI_MD_GFM, XUI_MD_EXTENDED
    };
    unsigned variant, run_count, combination, failures = 0, combinations = 0;
    for (variant = 0; variant < sizeof(words) / sizeof(*words); variant++)
      for (run_count = 3; run_count <= (variant == 2 ? 6u : variant < 2 ? 4u : 3u); run_count++)
        for (combination = 0; combination < (1u << (2 * run_count)); combination++) {
            xui_document rich = NULL, markdown = NULL;
            xui_document_transaction txn = NULL;
            xui_document_snapshot snapshot = NULL;
            xui_doc_node_desc_t node = {0};
            uint32_t run_marks[6] = {0};
            uint64_t paragraph, id, total = 0;
            unsigned i, dialect_index;
            combinations++;
            for (i = 0; i < run_count; i++)
                run_marks[i] = marks[(combination >> (2 * i)) & 3];
            CHECK(xuiDocumentCreate(NULL, &rich) == XUI_OK &&
                xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
            node.iSize = sizeof(node); node.iKind = XUI_DOC_PARAGRAPH;
            CHECK(xuiDocumentTxnInsertNode(txn, 1, UINT64_MAX,
                &node, &paragraph) == XUI_OK);
            for (i = 0; i < run_count; i++) {
                node.iKind = XUI_DOC_TEXT;
                node.tAttributes.iMarks = run_marks[i];
                node.sText = words[variant][i];
                node.iTextBytes = strlen(words[variant][i]);
                CHECK(xuiDocumentTxnInsertNode(txn, paragraph,
                    UINT64_MAX, &node, &id) == XUI_OK);
            }
            CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK);
            xuiDocumentTxnRelease(txn);
            CHECK(xuiDocumentAcquireSnapshot(rich, &snapshot) == XUI_OK);
            for (dialect_index = 0; dialect_index < 3; dialect_index++) {
                int result = xuiDocumentSnapshotAnalyzeMarkdownConversion(snapshot,
                    dialects[dialect_index], NULL, 0, &total);
                if (result != XUI_OK || total) {
                    fprintf(stderr, "Adjacent mark transition variant %u/%u: combination %u dialect %u lost (%llu), error %d\n",
                        variant, run_count, combination, dialects[dialect_index],
                        (unsigned long long)total, result);
                    failures++;
                } else {
                    CHECK(xuiDocumentSnapshotConvertToMarkdown(snapshot,
                        dialects[dialect_index], &markdown) == XUI_OK && markdown);
                    xuiDocumentRelease(markdown); markdown = NULL;
                }
            }
            xuiDocumentSnapshotRelease(snapshot);
            xuiDocumentRelease(rich);
        }
    CHECK(failures == 0);
    printf("Rich to Markdown: %u spaced/punctuation/Unicode plain/bold/italic combinations round-trip in three dialects\n",
        combinations);
}
static void markdown_rich_conversion_cases(void)
{
    const char* source = "[site][r]\n\n[r]: /go \"title\"\n[unused]: /hidden\n";
    xui_doc_desc_t desc = {0};
    xui_doc_rich_conversion_report_t report = {0};
    xui_doc_node_info_t info = {0};
    xui_document markdown, rich = NULL;
    xui_document_snapshot original, converted;
    xui_document_transaction txn;
    uint64_t text_id, bytes;
    char actual[128];
    desc.iSize = sizeof(desc); desc.iProfile = XUI_DOCUMENT_MARKDOWN;
    CHECK(xuiDocumentCreate(&desc, &markdown) == XUI_OK);
    CHECK(xuiDocumentLoadMarkdown(markdown, source, strlen(source)) == XUI_OK);
    CHECK(xuiDocumentAcquireSnapshot(markdown, &original) == XUI_OK);
    xuiDocumentRelease(markdown);
    report.iSize = sizeof(report);
    CHECK(xuiDocumentSnapshotAnalyzeRichConversion(original, &report) == XUI_OK &&
        report.iSourceBytes == strlen(source) && report.iReferenceDefinitions == 2 &&
        (report.iReasons & (XUI_DOC_RICH_LOSS_SOURCE_SYNTAX |
            XUI_DOC_RICH_LOSS_REFERENCE_DEFINITIONS)) ==
            (XUI_DOC_RICH_LOSS_SOURCE_SYNTAX | XUI_DOC_RICH_LOSS_REFERENCE_DEFINITIONS));
    CHECK(xuiDocumentSnapshotConvertToRich(original, 0, &rich) ==
        XUI_DOC_ERROR_UNREPRESENTABLE && rich == NULL);
    CHECK(xuiDocumentSnapshotConvertToRich(original, XUI_DOC_RICH_LOSS_SOURCE_SYNTAX,
        &rich) == XUI_DOC_ERROR_UNREPRESENTABLE && rich == NULL);
    CHECK(xuiDocumentSnapshotConvertToRich(original, 8u, &rich) ==
        XUI_ERROR_INVALID_ARGUMENT && rich == NULL);
    CHECK(xuiDocumentSnapshotConvertToRich(original,
        XUI_DOC_RICH_LOSS_SOURCE_SYNTAX | XUI_DOC_RICH_LOSS_REFERENCE_DEFINITIONS,
        &rich) == XUI_OK && rich && !xuiDocumentIsDirty(rich));
    CHECK(xuiDocumentGetProfile(rich) == XUI_DOCUMENT_RICH);
    CHECK(xuiDocumentAcquireSnapshot(rich, &converted) == XUI_OK);
    text_id = find_kind(converted, 1, XUI_DOC_TEXT);
    info.iSize = sizeof(info);
    CHECK(xuiDocumentSnapshotGetNode(converted, text_id, &info) == XUI_OK &&
        (info.tAttributes.iMarks & XUI_DOC_LINK) &&
        !strcmp(info.sResource, "/go") && !strcmp(info.sTitle, "title"));
    expect_text(converted, text_id, "site");
    CHECK(xuiDocumentSnapshotCopySource(converted, actual, sizeof(actual), &bytes) ==
        XUI_ERROR_UNSUPPORTED);
    xuiDocumentSnapshotRelease(converted);
    CHECK(xuiDocumentBeginTransaction(rich, NULL, &txn) == XUI_OK);
    CHECK(xuiDocumentTxnReplaceText(txn, text_id, 0, 4, "new", 3) == XUI_OK);
    CHECK(xuiDocumentTxnCommit(txn, NULL) == XUI_OK); xuiDocumentTxnRelease(txn);
    CHECK(xuiDocumentUndo(rich, NULL) == XUI_OK && !xuiDocumentIsDirty(rich));
    xuiDocumentRelease(rich); rich = NULL;
    CHECK(xuiDocumentSnapshotCopySource(original, actual, sizeof(actual), &bytes) == XUI_OK &&
        bytes == strlen(source) && !strcmp(actual, source));
    xuiDocumentSnapshotRelease(original);

    CHECK(xuiDocumentCreate(&desc, &markdown) == XUI_OK);
    CHECK(xuiDocumentLoadMarkdown(markdown, "", 0) == XUI_OK);
    CHECK(xuiDocumentAcquireSnapshot(markdown, &original) == XUI_OK);
    report.iSize = sizeof(report);
    CHECK(xuiDocumentSnapshotAnalyzeRichConversion(original, &report) == XUI_OK &&
        report.iReasons == 0 && report.iSourceBytes == 0);
    CHECK(xuiDocumentSnapshotConvertToRich(original, 0, &rich) == XUI_OK && rich);
    xuiDocumentRelease(rich); xuiDocumentSnapshotRelease(original); xuiDocumentRelease(markdown);

    CHECK(xuiDocumentCreate(&desc, &markdown) == XUI_OK);
    CHECK(xuiDocumentLoadMarkdown(markdown, "| A | B |\n| - | - |\n| x | y |\n", 30) == XUI_OK);
    CHECK(xuiDocumentAcquireSnapshot(markdown, &original) == XUI_OK);
    report.iSize = sizeof(report);
    CHECK(xuiDocumentSnapshotAnalyzeRichConversion(original, &report) == XUI_OK &&
        report.iReasons == XUI_DOC_RICH_LOSS_SOURCE_SYNTAX &&
        report.iReferenceDefinitions == 0);
    CHECK(xuiDocumentSnapshotConvertToRich(original, XUI_DOC_RICH_LOSS_SOURCE_SYNTAX,
        &rich) == XUI_OK && rich);
    CHECK(xuiDocumentAcquireSnapshot(rich, &converted) == XUI_OK);
    CHECK(find_kind(converted, 1, XUI_DOC_TABLE) != 0 &&
        find_kind(converted, 1, XUI_DOC_CELL) != 0);
    xuiDocumentSnapshotRelease(converted); xuiDocumentRelease(rich);
    xuiDocumentSnapshotRelease(original); xuiDocumentRelease(markdown);
    puts("Markdown to Rich: explicit source/reference loss acceptance, semantic copy and editable history passed");
}
