        CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
        CHECK(xuiDocumentTxnInsertRule(t, &range, &rule, &caret) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
        CHECK(xuiDocumentAcquireSnapshot(d, &snap) == XUI_OK);
        CHECK(xuiDocumentSnapshotGetNode(snap, rule, &info) == XUI_OK && info.iKind == XUI_DOC_RULE);
        CHECK(caret.iKind == XUI_DOC_POSITION_GAP); xuiDocumentSnapshotRelease(snap);
        CHECK(xuiDocumentUndo(d, NULL) == XUI_OK); test_source(d, original, 1);
        range = test_find(d, "beforeafter"); range.tAnchor.iOffset = range.tCaret.iOffset = 6;
        revision = xuiDocumentGetRevision(d);
        CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
        CHECK(xuiDocumentTxnInsertCodeBlock(t, &range, "bad lang", "x", 1,
            &code, &caret) == XUI_ERROR_INVALID_ARGUMENT);
        xuiDocumentTxnRelease(t);
        CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
        CHECK(xuiDocumentTxnInsertCodeBlock(t, &range, "mermaid", "graph TD", 8,
            &code, &caret) == XUI_DOC_ERROR_UNREPRESENTABLE);
