static void code_and_rule_insert_failures(void)
{
    unsigned mode;
    for (mode = 0; mode < 2; mode++) {
        long point; int success = 0;
        for (point = 0; point < 2000 && !success; point++) {
            fail_allocator a = {-1, 0}; xui_doc_desc_t desc = {0}; xui_document d;
            xui_document_snapshot before, after; xui_document_transaction t = NULL;
            xui_doc_range_t range; xui_doc_position_t caret;
            uint64_t block, revision; int result, can_undo;
            desc.iSize = sizeof(desc); desc.iProfile = XUI_DOCUMENT_MARKDOWN;
            desc.iMarkdownDialect = XUI_MD_EXTENDED;
            desc.onAlloc = failing_alloc; desc.onFree = failing_free; desc.pAllocatorUser = &a;
            CHECK(xuiDocumentCreate(&desc, &d) == XUI_OK &&
                xuiDocumentLoadMarkdown(d, "a  b\n", 5) == XUI_OK);
            CHECK(xuiDocumentAcquireSnapshot(d, &before) == XUI_OK);
            range = test_find(d, "a  b"); range.tAnchor.iOffset = range.tCaret.iOffset = 2;
            revision = xuiDocumentGetRevision(d); can_undo = xuiDocumentCanUndo(d);
            a.remaining = point;
            result = xuiDocumentBeginTransaction(d, NULL, &t);
            if (result == XUI_OK) result = mode ?
                xuiDocumentTxnInsertRule(t, &range, &block, &caret) :
                xuiDocumentTxnInsertCodeBlock(t, &range, "c", "x", 1, &block, &caret);
            if (result == XUI_OK) result = xuiDocumentTxnCommit(t, NULL);
            xuiDocumentTxnRelease(t); a.remaining = -1;
            if (result == XUI_OK) success = 1;
            else {
                CHECK(result == XUI_ERROR_OUT_OF_MEMORY &&
                    xuiDocumentGetRevision(d) == revision && xuiDocumentCanUndo(d) == can_undo);
                CHECK(xuiDocumentAcquireSnapshot(d, &after) == XUI_OK);
                expect_identity_tree(before, after, 1); xuiDocumentSnapshotRelease(after);
                test_source(d, "a  b\n", 1);
            }
            xuiDocumentSnapshotRelease(before); xuiDocumentRelease(d); CHECK(!a.live);
        }
        CHECK(success);
        printf("%s insertion allocation-failure sweep: %ld points; atomic source/tree/history and no leaks passed\n",
            mode ? "Rule" : "Code block", point);
    }
}
