        CHECK(xuiDocumentAcquireSnapshot(d, &restored) == XUI_OK);
        expect_identity_tree(before, restored, 1); xuiDocumentSnapshotRelease(restored);
        xuiDocumentSnapshotRelease(before); xuiDocumentRelease(d);
