        block = insert(t, outer_item, XUI_DOC_PARAGRAPH, NULL);
        insert(t, block, XUI_DOC_TEXT, "outer");
        nested = insert(t, outer_item, XUI_DOC_LIST, NULL);
        nested_item = insert(t, nested, XUI_DOC_LIST_ITEM, NULL);
