        CHECK(xuiDocumentTxnWrapQuoteRange(t, &range, &quote, &selected) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
        CHECK(xuiDocumentAcquireSnapshot(d, &snap) == XUI_OK);
        CHECK(find_kind(snap, 1, XUI_DOC_QUOTE) == quote &&
            find_kind(snap, quote, XUI_DOC_TEXT) == first);
        xuiDocumentSnapshotRelease(snap);
        caret = test_find(d, "alpha").tCaret; caret.iOffset = 2;
        CHECK(xuiDocumentBeginTransaction(d, NULL, &t) == XUI_OK);
        CHECK(xuiDocumentTxnUnwrapQuote(t, &caret, &caret) == XUI_OK);
        CHECK(xuiDocumentTxnCommit(t, NULL) == XUI_OK); xuiDocumentTxnRelease(t);
        CHECK(xuiDocumentAcquireSnapshot(d, &snap) == XUI_OK);
        CHECK(!find_kind(snap, 1, XUI_DOC_QUOTE) && find_kind(snap, 1, XUI_DOC_TEXT) == first);
