            if (result == XUI_OK) result = xuiDocumentTxnInsertFootnote(t,
                &range, mode == 0 || mode == 3 ? "n" : NULL,
                mode == 1 ? NULL : mode == 2 ? "New" : mode == 3 ? "One\nTwo" : "Note",
                mode == 1 ? 0 : mode == 2 ? 3 : mode == 3 ? 7 : 4,
                &reference, &footnote, &reference_caret, &body_caret);
