static void expect_extension_payload(xui_document_snapshot snapshot, uint64_t node,
    const unsigned char* expected, uint64_t expected_bytes, uint32_t version, int required)
{
    xui_doc_node_info_t info = {0};
    unsigned char copied[32] = {0};
    uint64_t bytes = UINT64_MAX;
    info.iSize = sizeof(info);
    CHECK(expected_bytes <= sizeof(copied));
    CHECK(xuiDocumentSnapshotGetNode(snapshot, node, &info) == XUI_OK &&
        info.iKind == XUI_DOC_EXTENSION && info.iExtensionVersion == version &&
        info.bExtensionRequired == required && info.iExtensionPayloadBytes == expected_bytes);
    CHECK(xuiDocumentSnapshotCopyExtensionPayload(snapshot, node, NULL, 0, &bytes) == XUI_OK &&
        bytes == expected_bytes);
    if (expected_bytes) {
        CHECK(xuiDocumentSnapshotCopyExtensionPayload(snapshot, node, copied,
            expected_bytes - 1, &bytes) == XUI_ERROR_BUFFER_TOO_SMALL && bytes == expected_bytes);
        CHECK(xuiDocumentSnapshotCopyExtensionPayload(snapshot, node, copied,
            expected_bytes, &bytes) == XUI_OK && !memcmp(copied, expected, (size_t)bytes));
    }
}
